<script lang="ts">import "@unofficial-krds/styles/all.css";import {untrack} from 'svelte';import CatalogExamples from './CatalogExamples.svelte';import {catalogSeed} from './catalog-state.js';let {componentId,caseId}:{componentId:string;caseId:string}=$props();let snapshot=$state<Record<string,any>>(untrack(()=>{const initial=catalogSeed(componentId,caseId);for(const record of initial.files??[]){const material=(initial.__host.fileFixtures??[]).find((x:any)=>x.id===(record.fileFixtureId??record.id)||x.name===record.file?.name)??record.file??record;record.file=new File([material.contents??material.text??'local fixture'],material.name??'example.txt',{type:material.type??'text/plain',lastModified:0});}return initial;}));function patch(next:Record<string,any>){snapshot={...snapshot,...next};}function emit(name:string,detail:any,next?:Record<string,any>){if(next){next={...next};for(const key of ['value','checked','open','index','playing','expandedId','expandedIds','expanded','mobileOpen','openIds','selectedTopicId','activePanel'])if(snapshot[key]===undefined)delete next[key];}if(next&&snapshot.__host.acceptChanges!==false&&!(name==='openChange'&&detail.open===false&&snapshot.__host.acceptClose===false))patch(next);}</script><CatalogExamples {componentId} state={snapshot} {emit} {patch}/>